import{_ as t,o as a,c as r,a5 as s}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Practice Map — Business, Discipline, and AI","description":"Choose a path through English, AI, entrepreneurship, or consistent practice, and turn four weeks of small actions into work, feedback, and decisions.","frontmatter":{"title":"Practice Map — Business, Discipline, and AI","description":"Choose a path through English, AI, entrepreneurship, or consistent practice, and turn four weeks of small actions into work, feedback, and decisions.","updated":"2026-09-19T00:00:00.000Z"},"headers":[],"relativePath":"en/practice.md","filePath":"en/practice.md","lastUpdated":1789776000000}'),i={name:"en/practice.md"};function o(n,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="practice-map-—-business-discipline-and-ai" tabindex="-1">Practice Map — Business, Discipline, and AI <a class="header-anchor" href="#practice-map-—-business-discipline-and-ai" aria-label="Permalink to &quot;Practice Map — Business, Discipline, and AI&quot;">​</a></h1><p>This map supplements the <a href="./threads/part-0/reader-guide">Reader’s Guide</a> with practical tasks in business, discipline, and AI. For the longer arc, see the <a href="./threads/part-5/90-day-plan">90-Day Action Plan</a>; the four weeks here are one adjustable experiment within that plan. You do not need to finish it before acting, or start English, a business, and an AI project at once. Choose one problem that exists this week and turn your reading into an action you can finish.</p><h2 id="choose-a-path-for-your-current-problem" tabindex="-1">Choose a path for your current problem <a class="header-anchor" href="#choose-a-path-for-your-current-problem" aria-label="Permalink to &quot;Choose a path for your current problem&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your situation</th><th>Start with</th><th>Evidence to keep this week</th></tr></thead><tbody><tr><td>You want to learn a skill with AI</td><td><a href="./threads/part-3/1-ai-learning">Learning Anything with AI</a> → <a href="./threads/practice/ai-workflows">AI Workflows</a></td><td>Work completed independently and a record of errors</td></tr><tr><td>You use AI but cannot judge its reliability</td><td><a href="./threads/practice/ai-evaluation">AI Evaluation and Reliability</a> → <a href="./templates/ai-evaluation">Evaluation Record</a></td><td>A small test set and an evidence-based version comparison</td></tr><tr><td>You have a business idea but have not met customers</td><td><a href="./threads/practice/customer-discovery">From Problems to First Customers</a> → <a href="./templates/startup-experiment">Startup Experiment</a></td><td>Real interview notes, including evidence against your hypothesis</td></tr><tr><td>People use your service, but the work does not pay</td><td><a href="./threads/practice/sustainable-business">A Sustainable Small Business</a></td><td>A delivery record including communication, rework, and support time</td></tr><tr><td>You struggle to start or return after a break</td><td><a href="./threads/practice/discipline-and-consistency">Discipline and Consistency</a> → <a href="./templates/consistency-plan">Consistency Plan</a></td><td>A clear cue, a smaller action, and an observable output</td></tr><tr><td>English limits your reading or communication</td><td><a href="./threads/part-1/0-cefr">CEFR Goals and Self-check</a> → <a href="./templates/english-diagnostic">English Diagnostic</a></td><td>A recording or short text with one priority for practice</td></tr></tbody></table><p>These outputs are starting suggestions, not universal performance requirements. If caring responsibilities, shift work, or unexpected events take your time, reduce the number of tasks while keeping a clear definition of completion.</p><h2 id="a-four-week-practice-path" tabindex="-1">A four-week practice path <a class="header-anchor" href="#a-four-week-practice-path" aria-label="Permalink to &quot;A four-week practice path&quot;">​</a></h2><p>This is an adjustable schedule, not a promise of income or mastery in four weeks. Try two 25-minute sessions and one 10-minute review each week, or spread a week of work across a longer period.</p><h3 id="week-one-establish-your-starting-point" tabindex="-1">Week one: establish your starting point <a class="header-anchor" href="#week-one-establish-your-starting-point" aria-label="Permalink to &quot;Week one: establish your starting point&quot;">​</a></h3><p>Fill in a <a href="./templates/learning-state">Learning State</a> for one problem. Save a baseline: explain something without AI, time an existing process, or ask a user about the last time a problem occurred. “Someone will probably need this” remains a hypothesis.</p><h3 id="week-two-make-the-smallest-useful-version" tabindex="-1">Week two: make the smallest useful version <a class="header-anchor" href="#week-two-make-the-smallest-useful-version" aria-label="Permalink to &quot;Week two: make the smallest useful version&quot;">​</a></h3><p>Choose something you can demonstrate. For English, write an email with a real purpose; for a business, deliver a small service manually; for AI, produce a summary with traceable sources. When AI is involved, use an <a href="./templates/ai-task-brief">AI Task Brief</a> to fix inputs, boundaries, and acceptance criteria. For a business idea, use a <a href="./templates/startup-experiment">Startup Experiment</a> to define the hypothesis and stopping rules. Complete one cycle first.</p><h3 id="week-three-collect-real-feedback" tabindex="-1">Week three: collect real feedback <a class="header-anchor" href="#week-three-collect-real-feedback" aria-label="Permalink to &quot;Week three: collect real feedback&quot;">​</a></h3><p>Give the output to an actual user, or test yourself independently on new material. Record what the user did and where they struggled, beyond “looks good.” Test an AI project with missing information, conflicting sources, and tool failures. For a business experiment, record silence, rejection, and reasons for not returning.</p><h3 id="week-four-decide-what-to-keep" tabindex="-1">Week four: decide what to keep <a class="header-anchor" href="#week-four-decide-what-to-keep" aria-label="Permalink to &quot;Week four: decide what to keep&quot;">​</a></h3><p>Use a <a href="./templates/weekly-review">Weekly Review</a> to compare the baseline with current evidence. Decide whether to continue, reduce scope, change the method, or stop, and record why. Carry one valuable action into the next cycle. Stopping a disproven approach is progress too.</p><h2 id="use-one-evidence-system-across-topics" tabindex="-1">Use one evidence system across topics <a class="header-anchor" href="#use-one-evidence-system-across-topics" aria-label="Permalink to &quot;Use one evidence system across topics&quot;">​</a></h2><p>A local folder is enough. There is no need to build a complex knowledge system first:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-practice/</span></span>
<span class="line"><span>  state.md       Current problem, baseline, next action</span></span>
<span class="line"><span>  attempts/      Work, tests, and deliveries</span></span>
<span class="line"><span>  feedback.md    User feedback, errors, and sources</span></span>
<span class="line"><span>  review.md      This week&#39;s decision and where to resume</span></span></code></pre></div><p>Keep only useful material. Obtain permission for other people&#39;s information and remove unnecessary identifying details. When sharing work publicly, exclude customer materials, private conversations, and credentials.</p><p>Judge a record by two questions: can you resume tomorrow, and can you explain the decision a month later?</p><h2 id="template-toolbox" tabindex="-1">Template toolbox <a class="header-anchor" href="#template-toolbox" aria-label="Permalink to &quot;Template toolbox&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Purpose</th><th>Templates</th></tr></thead><tbody><tr><td>Establish a baseline</td><td><a href="./templates/learning-state">Learning State</a>, <a href="./templates/english-diagnostic">English Diagnostic</a></td></tr><tr><td>Collaborate with AI</td><td><a href="./templates/ai-task-brief">Task Brief</a>, <a href="./templates/ai-learning-log">Learning Log</a>, <a href="./templates/ai-evaluation">Evaluation Record</a></td></tr><tr><td>Test a business idea</td><td><a href="./templates/startup-experiment">Startup Experiment</a>, <a href="./templates/ai-project-scorecard">AI Project Scorecard</a></td></tr><tr><td>Keep going and review</td><td><a href="./templates/rhythm-ledger">Rhythm Ledger</a>, <a href="./templates/consistency-plan">Consistency Plan</a>, <a href="./templates/weekly-review">Weekly Review</a>, <a href="./templates/ai-case-review">AI Case Review</a></td></tr></tbody></table><p>The Rhythm Ledger manages weekly capacity and rhythm; the Consistency Plan specifies one action experiment. Shorten any template. If filling it in takes longer than doing the work, keep only the task, evidence of completion, and next action.</p><h2 id="how-to-read-the-guide" tabindex="-1">How to read the guide <a class="header-anchor" href="#how-to-read-the-guide" aria-label="Permalink to &quot;How to read the guide&quot;">​</a></h2><p>Method chapters offer processes to try and test. Personal stories describe experience in a specific setting. Follow the sources to check external research and product information. Unless explicitly stated otherwise, example numbers, two-week cycles, and sample sizes are practical starting points, not scientific thresholds or business guarantees.</p><p>For background, read <a href="./threads/part-2/entrepreneurship">Entrepreneurship</a> and <a href="./threads/part-2/my-story">My Story</a>. When you are ready to act, return to your chosen path and finish your first piece of work.</p>`,26)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
